terms.medium_def:
A location near Diblathaim only mentioned at Ezk.39.11; 
only referred to as Travelers_Valley (עָבַר גַּיְא). §
Combined with gay (גַּיְא "Valley" H1516O)

A man living at the time of the Patriarchs, first mentioned at Gen.10.21; 
referred to as Eber (עֵ֫בֶר), or Eber (Ἐβέρ); 
a son of Shelah; 
father of Peleg and Joktan.

A man from the tribe of Gad living at the time of Divided Monarchy, only mentioned at 1Ch.5.13; 
only referred to as Eber (עֵ֫בֶר); 
son of Abihail; 
a brother of Michael, Meshullam, Sheba, Jorai, Jacan and Zia.

A man from the tribe of Benjamin living at the time of Divided Monarchy, only mentioned at 1Ch.8.12; 
only referred to as Eber (עֵ֫בֶר); 
son of Elpaal; 
a brother of Misham, Shemed, Beriah, Shema, Zebadiah, Meshullam, Hizki, Heber, Ishmerai, Izliah and Jobab.

A man from the tribe of Benjamin living at the time of Divided Monarchy, only mentioned at 1Ch.8.22; 
only referred to as Eber (עֵ֫בֶר); 
son of Shashak; 
a brother of Ishpan, Eliel, Abdon, Zichri, Hanan, Hananiah, Elam, Anthothijah, Iphdeiah and Penuel.

A man from the tribe of Levi living at the time of Divided Monarchy, only mentioned at 1Ch.24.27; 
only referred to as Ibri (עִבְרִי); 
son of Jaaziah; 
a brother of Beno, Shoham and Zaccur. § a Merarite Levite of the family of Jaaziah in the time of David

A man living at the time of Exile and Return, only mentioned at Neh.3.10; 
only referred to as Harumaph (חֲרוּמַף); 
father of Jedaiah. § father of Jedaiah, one of the builders of the wall in Nehemiah's time

People from Aph(?) from the tribe of Judah, first mentioned at 1Ch.2.30; 
only referred to as Appaim (אַפַּיִם); 
descended from Nadab along with Seled; 
progenitors of Ishi. § a son of Nadab

Caleb's father living at the time of Egypt and Wilderness, first mentioned at Num.13.6; 
only referred to as Jephunneh (יְפֻנֶּה); 
father of Caleb, Kenaz.

A man from the tribe of Asher living at the time of Divided Monarchy, only mentioned at 1Ch.7.38; 
only referred to as Jephunneh (יְפֻנֶּה); 
son of Ithran; 
a brother of Pispa and Ara.

A man from the tribe of Judah living at the time of Egypt and Wilderness, only mentioned at 1Ch.4.4; 
only referred to as Penuel (פְּנוּאֵל); 
son of Hur; 
a brother of Uri, Shobal, Salma, Hareph, Jezreel, Ishma, Idbash, Hazzelelponi and Ezer.

A man from the tribe of Benjamin living at the time of Divided Monarchy, only mentioned at 1Ch.8.25; 
only referred to as Penuel (פְּנוּאֵל); 
son of Shashak; 
a brother of Ishpan, Eber, Eliel, Abdon, Zichri, Hanan, Hananiah, Elam, Anthothijah and Iphdeiah; 
founder of Gedor.

People from Nephil(?), first mentioned at Gen.6.4; 
only referred to as Nephilim (נְפִלִים). §People from Nephil(?), first mentioned at Gen.6.4 
giants, the Nephilim

A location in Jerusalem only mentioned at Neh.12.39; 
only referred to as Guard_Gate (מַטָּרָה). §
This name means guard, prison

A man living at the time of the Patriarchs, first mentioned at Gen.10.22; 
only referred to as Elam (עֵילָם); 
son of Shem; 
a brother of Asshur, Arpachshad, Lud and Aram. §Male living at the time of the first Patriarchs (Gen.10.22; 1Ch.1.17)

A man from the tribe of Benjamin living at the time of Divided Monarchy, only mentioned at 1Ch.8.24; 
only referred to as Elam (עֵילָם); 
son of Shashak; 
a brother of Ishpan, Eber, Eliel, Abdon, Zichri, Hanan, Hananiah, Anthothijah, Iphdeiah and Penuel. §Male living at the time of the first Patriarchs (Gen.10.22; 1Ch.1.17)

A man living at the time of Divided Monarchy, only mentioned at 1Ch.26.3; 
only referred to as Elam (עֵילָם); 
son of Meshelemiah; 
a brother of Zechariah, Jediael, Zebadiah, Jathniel, Jehohanan and Eliehoenai. §Male living at the time of the first Patriarchs (Gen.10.22; 1Ch.1.17)

A man from the tribe of Simeon living at the time of Divided Monarchy, only mentioned at 1Ch.4.26; 
only referred to as Hammuel (חַמּוּאֵל); 
a son of Mishma; 
father of Zaccur. § a man of Simeon, of the family of Shaul

A man from the tribe of Judah living at the time of Divided Monarchy, only mentioned at 1Ch.2.55; 
only referred to as Hammath (חַמַּת); 
father or founder of Rechabites. § father of the house of Rechab
